using Cogpunk.Core.Templates;
using Microsoft.Xna.Framework;
using Terraria;
using Terraria.ID;
using Terraria.ModLoader;

namespace Cogpunk.Content.OldBrassTown.Tiles
{
	/// <summary>
	/// Brass Sandstone (2026-11-03): the rock of Old Brass Town's cavern, warm sandstone in strata with flecks of brass gone
	/// green. Natural; mined like vanilla's sandstone (no pickaxe gate). Generated by <see cref="Generation.OldBrassTownPass"/>.
	/// </summary>
	public class BrassSandstoneTile : CogpunkTile
	{
		public override void SetStaticDefaults() {
			TileID.Sets.GeneralPlacementTiles[Type] = false;   // later world-gen features (micro biomes, other mods) keep off the town
			Main.tileSolid[Type] = true;
			Main.tileBlockLight[Type] = true;
			MineResist = 1.2f;
			DustType = DustID.Sand;
			AddMapEntry(new Color(205, 150, 92), CreateMapEntryName());
			RegisterItemDrop(ModContent.ItemType<Items.BrassSandstone>());
		}
	}
}
